import{z as i,x as B,o as E,c as n,q as l,j as o,D as e,d as s,s as A,S as r}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Beam Search vs Sampling","description":"","frontmatter":{"title":"Beam Search vs Sampling","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/beam-vs-sample.md","filePath":"llm/beam-vs-sample.md","lastUpdated":1791413859000}'),p={name:"llm/beam-vs-sample.md"};function m(d,a,h,u,c,D){const t=B("Mermaid");return E(),n("div",null,[a[2]||(a[2]=l('<h1 id="beam-search-vs-sampling" tabindex="-1">Beam Search vs Sampling <a class="header-anchor" href="#beam-search-vs-sampling" aria-label="Permalink to &quot;Beam Search vs Sampling&quot;">​</a></h1><div class="epigraph"><p>极大似然解码——包括束搜索——会把文本推向重复、泛化与不自然；从截断的核里采样，才能回到人写的分布附近。</p><footer>—— Holtzman et al., The Curious Case of Neural Text Degeneration, ICLR 2020</footer></div><p>解码有两条经常被混为一谈的路。束搜索（beam search）维护 \\(B\\) 条最高 <em>对数概率和</em> 的前缀，逐步扩展，近似寻找 \\(\\arg\\max_y \\log\\pi(y\\mid x)\\)。采样从 \\(\\pi\\) 或其截断（温度、top-\\(k\\)、nucleus）里随机抽下一个 token。机器翻译时代束几乎是默认；对话与开放生成里，Holtzman 等人指出束会退化。推理模型与强化学习又把采样抬成一等公民：没有多样性就没有<a href="/llm/best-of-n">Best-of-N</a>，也没有组相对训练。本篇对照两种搜索在 <em>目标函数</em> 上的差别，而不是罗列解码器 API。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自回归把 \\(p(y\\mid x)\\) 拆成逐步条件。精确 MAP 是指数级搜索。贪心 \\(B=1\\) 的束每步取最大，局部最优且对早期错误无法回头。加大 \\(B\\) 更接近 MAP，但 MAP 本身未必是人想要的对象：语言模型在「安全的高频续写」上概率质量很高，重复短语、万能套话的联合对数概率可以高过一条具体而正确的推理。</p><p>采样的问题相反：一次抽取方差大，短指令上胡话概率不可忽略；温度过高则破坏已经学好的语法。需要分清任务：要 <em>一个高概率的合法字符串</em>（格式化代码、受约束模板），束或约束解码更合适；要 <em>覆盖多种推理路径</em> 再交给核对器，必须采样。把束的 \\(B\\) 加大当成「也是一种 Best-of-N」，比较的是不同的集合——束里的条高度相关，BoN 里的条在独立采样假设下才近似无关。</p><h3 id="目标函数先于实现" tabindex="-1">目标函数先于实现 <a class="header-anchor" href="#目标函数先于实现" aria-label="Permalink to &quot;目标函数先于实现&quot;">​</a></h3><p>束优化的是 \\(\\sum_t \\log\\pi(y_t\\mid \\mathrm{prefix})\\)，长度偏置明显：更长的序列对数和更负，实现常除以长度或加长度惩罚，否则束爱提前结束。采样优化的不是一个确定的 \\(y^\\star\\)，而是从分布取矩。强化学习的期望回报 \\(\\mathbb{E}_{y\\sim\\pi}[R]\\) 与采样同构，与 MAP 不同构。用束生成的轨迹去估 REINFORCE 梯度，等于对错误的分布求期望。</p><p><span class="marginnote">长度偏置可以这样理解：对数概率是把每步的（负）对数概率连加，每多写一个 token 就多加一个负数，所以序列越长总分天然越负。初学者容易以为模型&quot;不喜欢&quot;长文本，实际上这只是打分方式的副作用，所以要除以长度或加惩罚来纠正。</span></p><p><span class="marginnote">nucleus（top-\\(p\\)）不是另一种束。它在每一步把概率质量累计到 \\(p\\) 的最小 token 集上再归一化，然后 <em>随机</em> 抽。束在每一步是确定性的保留 Top-\\(B\\) 前缀。一个改支撑集，一个改搜索宽度。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>束：\\(t=0\\) 从 BOS/提示结束处扩展；每步对每条存活前缀展开词表，按累计对数概率留 \\(B\\) 条。结束条件是全部存活条遇到 EOS 或达到最大长度。最终可取最高分的一条，或把 \\(B\\) 条再交给外部 \\(s\\) 做一次重排——后者已接近「束 + 验证器」，仍不是独立 BoN。</p><p>采样：每步从 \\(\\mathrm{softmax}(z/T)\\) 抽，可选地先把 logits 截成 top-\\(k\\) 或 nucleus。\\(T\\to 0\\) 退化为贪心，与 \\(B=1\\) 的束重合。\\(T=1\\) 且无截断时，抽取的是模型的原始条件分布，这是策略梯度假设的那一个。训练 rollout 应记录当时的 \\(T\\) 与截断，推理若改贪心，行为会偏。</p><p><span class="marginnote">温度 \\(T\\) 就是把每个 logit 除以一个数再 softmax：\\(T\\lt 1\\) 把概率差距拉大，模型更&quot;自信&quot;；\\(T\\gt 1\\) 把差距抹平，低概率词也更敢抽。比如 top-2 两个 token 的概率是 0.9 与 0.1，把 \\(T\\) 调高后可能变成 0.6 与 0.4——词汇池没变，只是下注方式变了。</span></p>',14)),(E(),o(r,null,{default:e(()=>[A(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%89%8D%E7%BC%80%22%5D%20--%3E%20B%7B%22%E8%A7%A3%E7%A0%81%E7%9B%AE%E6%A0%87%22%7D%0A%20%20B%20--%3E%7C%22%E8%BF%91%E4%BC%BC%20MAP%22%7C%20BEAM%5B%22%E6%9D%9F%EF%BC%9A%E4%BF%9D%E7%95%99%20B%20%E6%9D%A1%E6%9C%80%E9%AB%98%20%CE%A3%20log%20%CF%80%22%5D%0A%20%20B%20--%3E%7C%22%E5%8C%B9%E9%85%8D%20%CF%80%20%E6%88%96%E8%A6%81%E5%A4%9A%E6%A0%B7%E6%80%A7%22%7C%20SAM%5B%22%E9%87%87%E6%A0%B7%EF%BC%9A%E6%B8%A9%E5%BA%A6%20%2F%20nucleus%22%5D%0A%20%20BEAM%20--%3E%20DEG%5B%22%E9%AB%98%E6%A6%82%E7%8E%87%E5%A5%97%E8%AF%9D%E3%80%81%E9%87%8D%E5%A4%8D%E9%A3%8E%E9%99%A9%22%5D%0A%20%20SAM%20--%3E%20VAR%5B%22%E5%8D%95%E6%AC%A1%E6%96%B9%E5%B7%AE%E5%A4%A7%22%5D%0A%20%20SAM%20--%3E%20BON%5B%22N%20%E6%AC%A1%E7%8B%AC%E7%AB%8B%E6%8A%BD%20%E2%86%92%20Best-of-N%20%2F%20RL%22%5D%0A%20%20BEAM%20--%3E%20RERANK%5B%22%E5%8F%AF%E9%80%89%EF%BC%9A%E5%A4%96%E9%83%A8%20s%20%E9%87%8D%E6%8E%92%20B%20%E6%9D%A1%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<h3 id="与树搜索的位置" tabindex="-1">与树搜索的位置 <a class="header-anchor" href="#与树搜索的位置" aria-label="Permalink to &quot;与树搜索的位置&quot;">​</a></h3><p>束是宽度固定、不回溯的树搜索，打分是模型自身的对数概率。PRM 引导的束把逐步分数换成过程奖励，目标函数已经不是 \\(\\log\\pi\\)，见<a href="/llm/prm-guided-search">过程奖励引导的搜索</a>。<a href="/llm/mcts-llm">MCTS</a> 再引入访问次数与探索项，宽度随模拟预算变。三者不要画成一条「B 越大越强」的轴：改的是评分、探索与是否允许降低即时 \\(\\log\\pi\\) 去换更高的外部 \\(s\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>退化来自概率质量集中在短循环与泛化连接词上。束每步都强化当前最高质量，一旦进入重复圈，圈内续写的条件概率极高，很难被挤出。采样即使支撑集里有重复 token，随机性仍有机会跳出；nucleus 把长尾噪声切掉，避免抽到完全不相关的词，同时保留头部的多模式。开放生成里这通常比加大 \\(B\\) 更有效，Holtzman 等人的人工与自动指标都指向这一点。</p>',4)),(E(),o(r,null,{default:e(()=>[A(t,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E7%BB%AD%E5%86%99%E8%BF%9B%E5%85%A5%E9%AB%98%E9%A2%91%E7%9F%AD%E8%AF%AD%22%5D%20--%3E%20Q%7B%22%E4%B8%8B%E4%B8%80%E6%AD%A5%E6%80%8E%E4%B9%88%E8%B5%B0%22%7D%0A%20%20Q%20--%3E%7C%22%E6%9D%9F%22%7C%20L1%5B%22%E5%9C%88%E5%86%85%E7%BB%AD%E5%86%99%E6%A6%82%E7%8E%87%E6%9C%80%E9%AB%98%22%5D%0A%20%20L1%20--%3E%20L2%5B%22%E6%AF%8F%E6%AD%A5%E5%8F%AA%E5%BC%BA%E5%8C%96%E6%9C%80%E9%AB%98%E5%88%86%E8%B7%AF%E5%BE%84%22%5D%0A%20%20L2%20--%3E%20LOOP%5B%22%E8%A2%AB%E9%94%81%E8%BF%9B%E9%87%8D%E5%A4%8D%E5%9C%88%22%5D%0A%20%20Q%20--%3E%7C%22%E9%87%87%E6%A0%B7%22%7C%20R1%5B%22%E9%9A%8F%E6%9C%BA%E6%80%A7%E5%85%81%E8%AE%B8%E6%8A%BD%E9%9D%9E%E6%9C%80%E4%BC%98%E8%AF%8D%22%5D%0A%20%20R1%20--%3E%20R2%5B%22nucleus%20%E5%88%87%E6%8E%89%E9%95%BF%E5%B0%BE%E5%99%AA%E5%A3%B0%22%5D%0A%20%20R2%20--%3E%20ESC%5B%22%E8%B7%B3%E5%87%BA%E5%BE%AA%E7%8E%AF%E4%B8%94%E4%BB%8D%E9%80%9A%E9%A1%BA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l('<p>这条流程回答的问题是：为什么同一份模型权重，换成解码方式就出现&quot;复读机&quot;行为。圈内的续写本身确实是条件概率最高的动作，束只是忠实地每步选它；采样的随机性此时反而是解药。</p><p>在可核对任务上，机制反转：错误推理的 \\(\\log\\pi\\) 可能低于正确推理（模型「知道」正确格式），束有机会直接找到对的；也可能正确推理更长、对数和更低，束反而选短的错解。长度归一化、覆盖惩罚、外部验证器，都是在承认 <strong>\\(\\log\\pi\\) 不是任务损失</strong>。RL 训练过的推理模型进一步把质量从「短而常见」推到「长而可验证」，此时再用纯 \\(\\log\\pi\\) 束，等于用旧目标去搜新策略。</p><p><span class="marginnote">同一条束里的 \\(B\\) 条共享大量前缀，KV 可以一次算完再分叉，prefill 友好；独立采样的 \\(N\\) 条只共享用户提示前缀。服务实现上束未必更贵，但 <em>有效假设覆盖</em> 通常远小于独立 \\(N=B\\)。比公平应用「外部 \\(s\\) 下的准确率 / 总生成 token」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><h3 id="产品默认不要两套解码混用而不声明" tabindex="-1">产品默认不要两套解码混用而不声明 <a class="header-anchor" href="#产品默认不要两套解码混用而不声明" aria-label="Permalink to &quot;产品默认不要两套解码混用而不声明&quot;">​</a></h3><p>聊天助手用 nucleus 采样保持自然；代码补全用贪心或小束保持确定性；竞赛题用采样 + BoN 或思维链。若评测脚本是贪心，用户产品是 \\(T=0.8\\)，数字对不上。约束解码（正则、JSON schema）可以叠在束或采样上：约束改的是逐步合法集，不自动消除退化，也不自动给出多样性。</p><p>不要用「束宽 32」的准确率去对比「sample 32 + 多数票」而不报相关性。前者是近重复的高似然簇，后者才接近 pass@\\(N\\) 的覆盖。安全过滤应作用在最终字符串上：束可能稳定生成高似然的违规套话，采样可能偶发违规但也可偶发拒绝——两种失败要分开测。训练与推理温度不一致时，先修这个再调 \\(B\\)。</p><p><span class="marginnote">数字实例看覆盖公式：单条路径成功率只有 \\(p=0.3\\) 时，独立抽 \\(N=8\\) 次至少中一次的概率是 \\(1-0.7^8\\approx 94\\%\\)；但若 8 条样本高度相关（像同一束里那样），实际覆盖可能还不到一半。多样性买的就是这个 \\(1-(1-p)^N\\)。</span></p><p><span class="marginnote">出处以 Holtzman et al., ICLR 2020 为主；束搜索本身是经典序列解码，不必给它编造 2024 年的新 arXiv。OpenAI o1 的解码器未公开到束宽这一层，不要写进对照表。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>束近似 MAP（对数概率和），采样实现 \\(\\pi\\) 或其截断；目标函数不同，不能只比「宽度」。</li><li>开放生成里 MAP 导致重复与套话；nucleus 等截断采样是针对退化，不是针对数学准确率。</li><li>可核对任务上 \\(\\log\\pi\\) 仍可能与真值冲突，需要长度处理或外部 \\(s\\)。</li><li>RL / BoN / 组相对都假设独立采样；用束轨迹去估策略梯度是分布错误。</li><li>束内条高度相关，独立样本的 \\(N\\) 才对应覆盖 \\(1-(1-p)^N\\)。</li><li>评测解码必须与产品解码一致，温度和截断属于协议的一部分。</li><li>出处：Holtzman et al., <em>The Curious Case of Neural Text Degeneration</em>, ICLR 2020。</li></ul>',11))])}const f=i(p,[["render",m]]);export{_ as __pageData,f as default};
